installer-gui-script.script:

function checkOS() {
    if (system.compareVersions(system.version.ProductVersion, '27.0') < 0) {
        my.result.title = 'Unsupported macOS Version';
        my.result.message = 'Lioness requires macOS 27 or later. Installing it on macOS ' + system.version.ProductVersion + ' could render your system in an unusable state.';
        my.result.type = 'Warning';
        return false;
    }
    return true;
}
